// Rewrites pre-language custom property names to the token language's, from spec/migration.json (generated by
// gen-tokens.mjs from each lever's `was`). Rewrites `--old` wherever it is a whole custom property name: `var(--old`,
// `--old:`, `"--old"` (setProperty, getPropertyValue, style objects), Tailwind `(--old)` and `[--old:…]`; and in
// scripts (ts, tsx, js, mjs, lua) a quoted compiled-theme key, `"nk-old"` / `'nk-old'` (vars["nk-old"]).
//
//   node packages/core/scripts/migrate-levers.mjs <path…> [--dry]
//
// Directories are walked (node_modules, dist and synced components/ui skipped: `pnpm sync` re-copies those).
// Prints each file changed and how many names it rewrote; --dry changes nothing.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const MAP = JSON.parse(fs.readFileSync(path.join(here, "../spec/migration.json"), "utf8"));
const args = process.argv.slice(2);
const DRY = args.includes("--dry");
const roots = args.filter((a) => !a.startsWith("--"));
if (!roots.length) {
  console.error("usage: node packages/core/scripts/migrate-levers.mjs <path…> [--dry]");
  process.exit(2);
}

const EXT = /\.(css|tpl|tsx?|jsx?|mjs|lua|md|html|json)$/;
const SKIP = /(^|\/)(node_modules|dist|out|\.git)(\/|$)|\/components\/ui\/|spec\/migration\.json$|\/src\/spec\/|tokens\.generated\.ts$|\/test\/fixtures\//;
// nuikit_chat namespaces the whole palette under --nk-* (--nk-border is its border colour): only kit names move there
const PALETTE_PREFIXED = /\/nuikit_chat\/theme\/|chat-theme\.test/;
const PALETTE = /^nk-(border|radius|ring|accent|background|card|destructive|foreground|input|muted|popover|primary|secondary|font-|px|tone)/;
// longest names first, as one alternation; a name ends where a name character can't follow
const names = Object.keys(MAP).sort((a, b) => b.length - a.length);
const ALT = names.map((n) => n.replace(/[-]/g, "\\-")).join("|");
const RE = new RegExp(`--(${ALT})(?![\\w-])`, "g");
const KEY = new RegExp(`(["'\`])(${ALT})\\1`, "g");
const SCRIPT = /\.(tsx?|jsx?|mjs|lua)$/;
// quoted keys only where they are theme keys: not the class tables cn() merges (lib/utils.ts, kit-merge) or the
// intents schema, whose "nk-edge" / "nk-rise" are utility classes that share an old token's spelling
const NO_KEYS = /\/lib\/utils\.ts$|intents|kit-merge\.mjs$/;

let files = 0;
let total = 0;
const walk = (p) => {
  const st = fs.statSync(p);
  if (st.isDirectory()) {
    if (SKIP.test(p + "/")) return;
    for (const f of fs.readdirSync(p)) walk(path.join(p, f));
    return;
  }
  if (!EXT.test(p) || SKIP.test(p)) return;
  const src = fs.readFileSync(p, "utf8");
  let n = 0;
  let out = src.replace(RE, (m, old) => {
    if (PALETTE_PREFIXED.test(p) && PALETTE.test(old)) return m;
    n++;
    return `--${MAP[old]}`;
  });
  if (SCRIPT.test(p) && !NO_KEYS.test(p))
    out = out.replace(KEY, (_m, q, old) => {
      n++;
      return `${q}${MAP[old]}${q}`;
    });
  if (!n) return;
  files++;
  total += n;
  console.log(`${p}: ${n}`);
  if (!DRY) fs.writeFileSync(p, out);
};
for (const r of roots) walk(path.resolve(r));
console.log(`${DRY ? "would rewrite" : "rewrote"} ${total} name(s) in ${files} file(s)`);
